def main():
    changed = 0
    for fname, items in FRAGMENTS.items():
        if not os.path.exists(fname):
            print("MISSING FILE", fname); return 1
        text = open(fname, encoding="utf-8").read()
        new = text
        added = []
        for marker, body in items:
            if marker in new:
                print("  skip (already there):", fname, marker); continue
            new = new.rstrip("\n") + "\n\n" + body
            added.append(marker)
        if added:
            bak = fname + ".bak_20261125"
            if not os.path.exists(bak):
                shutil.copyfile(fname, bak)
            open(fname, "w", encoding="utf-8").write(new)
            changed += 1
        print("%-26s added %-3d %s  sha %s  %d bytes" % (fname, len(added), added, hashlib.sha1(open(fname, "rb").read()).hexdigest()[:10], os.path.getsize(fname)))
    return 0
if __name__ == "__main__":
    sys.exit(main())
